// Self-hosted, base64-embedded Inter (Latin) + Almarai (Arabic) font files,
// injected as @font-face CSS into <head> at app startup (see
// ensureFontsInjected() below). Embedded directly rather than linked from
// Google Fonts' CDN -- same reasoning as the inlined images in
// build_standalone.py: this app deploys as a single self-contained
// index.html to cPanel, so a runtime dependency on an external font CDN
// would mean a flash-of-unstyled-text (or a fully broken font) on any
// slow/offline/flaky connection, and would be one more third-party request
// on every page load for no benefit over baking the ~210KB of font data in
// once at build time.
//
// Weight coverage: Inter ships 400/500/600/700, which is every fontWeight
// value used anywhere in the app (see theme.ts's `type` presets and a
// repo-wide grep for `fontWeight`). Almarai's available static weights are
// only 300/400/700/800 -- 400 and 700 are embedded here; a component
// requesting 500 or 600 while in Arabic mode gets the browser's normal
// nearest-available-weight fallback (400 or 700, whichever is closer),
// which is unremarkable, standard CSS behavior, not a bug.
//
// Almarai is embedded as its ARABIC-SCRIPT SUBSET ONLY (not its Latin
// subset) with a `unicode-range` restricting it to Arabic code points.
// Latin characters that appear inside Arabic-language UI (USD prices, the
// "AR"/"EN" toggle) fall through to Inter automatically via the
// font-family fallback list in applyFontFamily() below -- per-character
// font selection across a unicode-range boundary is standard CSS, not
// custom logic -- which both looks better (Almarai's Latin glyphs are
// stylistically a poor match for Inter-drawn UI chrome) and saves ~40KB
// over embedding Almarai's Latin subset too.

import { Platform } from 'react-native';

const INTER_400 = '';
const INTER_500 = '';
const INTER_600 = '';
const INTER_700 = '';
const ALMARAI_400_ARABIC = '';
const ALMARAI_700_ARABIC = '';

// Standard Arabic-script Unicode ranges (Arabic, Arabic Supplement, Arabic
// Extended-A, Presentation Forms A/B) -- matches what Google Fonts itself
// serves as the "arabic" subset for this family.
const ARABIC_UNICODE_RANGE =
  'U+0600-06FF, U+0750-077F, U+0870-088E, U+0890-0891, U+0898-08E1, U+08E3-08FF, U+FB50-FDFF, U+FE70-FE74, U+FE76-FEFC';

function fontFace(family: string, weight: number, base64: string, unicodeRange?: string) {
  return `@font-face {
  font-family: '${family}';
  font-style: normal;
  font-weight: ${weight};
  font-display: swap;
  src: url(data:font/woff2;base64,${base64}) format('woff2');${unicodeRange ? `\n  unicode-range: ${unicodeRange};` : ''}
}`;
}

const FONT_CSS = [
  fontFace('Inter', 400, INTER_400),
  fontFace('Inter', 500, INTER_500),
  fontFace('Inter', 600, INTER_600),
  fontFace('Inter', 700, INTER_700),
  fontFace('Almarai', 400, ALMARAI_400_ARABIC, ARABIC_UNICODE_RANGE),
  fontFace('Almarai', 700, ALMARAI_700_ARABIC, ARABIC_UNICODE_RANGE),
  // Root-level rule so every piece of text in the app picks up the active
  // language's font stack via ordinary CSS inheritance, not just the ones
  // that go through theme.ts's `type` presets (which also set fontFamily
  // explicitly -- belt and suspenders, not a conflict: same var()).
  `html, body, #root { font-family: var(--vevaty-font, 'Inter', system-ui, -apple-system, sans-serif); }`,
].join('\n\n');

let injected = false;

// Call once at app startup (see LanguageContext.tsx). No-op on native/SSR,
// same guard pattern as applyBrandColors/applyFavicon elsewhere in the app.
export function ensureFontsInjected() {
  if (Platform.OS !== 'web' || typeof document === 'undefined' || injected) return;
  injected = true;
  const style = document.createElement('style');
  style.setAttribute('data-vevaty-fonts', 'true');
  style.textContent = FONT_CSS;
  document.head.appendChild(style);
}

// Swaps the --vevaty-font custom property between the English and Arabic
// stacks. Called from LanguageContext.tsx alongside applyDocumentDirection
// (both on initial restore from storage and on every setLanguage), so the
// active UI language always drives which font is showing -- 'Almarai' for
// Arabic script, falling back to 'Inter' for any Latin characters mixed
// into Arabic-language screens (prices, the language toggle itself).
export function applyFontFamily(lang: 'en' | 'ar') {
  if (Platform.OS !== 'web' || typeof document === 'undefined') return;
  const stack =
    lang === 'ar'
      ? "'Almarai', 'Inter', system-ui, -apple-system, sans-serif"
      : "'Inter', system-ui, -apple-system, sans-serif";
  document.documentElement.style.setProperty('--vevaty-font', stack);
}
